def findDuplicatesRestore(nums):
    result = []

    # First pass: mark seen numbers
    for i in range(len(nums)):
        index = abs(nums[i]) - 1

        if nums[index] < 0:
            # This number is a duplicate
            result.append(abs(nums[i]))
        else:
            # Mark as seen
            nums[index] = -nums[index]

    # Second pass: restore original array (optional)
    for i in range(len(nums)):
        nums[i] = abs(nums[i])

    return result

