def findDuplicatesAddition(nums):
    n = len(nums)
    result = []

    for num in nums:
        # Get the original value (before any additions)
        original = (num - 1) % n
        index = original

        # Add n to mark this index as visited
        nums[index] += n

    # Find indices where value > 2n (visited twice)
    for i in range(n):
        if nums[i] > 2 * n:
            result.append(i + 1)

    return result

